// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint[] memory v) public {
        // 1. keep domain wide: arrays must have same length and _tos non-empty
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        // perform the call as the required sender
        address sender = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.prank(sender);
        // 2. use try/catch to handle possible revert from inner require / call
        bool ok;
        bool returned;
        try c.transfer(_tos, v) returns (bool ret) {
            ok = true;
            returned = ret;
        } catch {
            ok = false;
        }
        // 3. property: if did not revert, return value must be true
        assertTrue(!ok || returned);
    }
}

